package plasmon.bsp

class MillUserCodeRewritesTests extends munit.FunSuite {

  private val tq = "\"\"\""

  // What Mill 1.4.0-M2 generates out of a package.mill with an object `package`
  // (out/mill-build/generatedScriptSources.dest/wrapped)
  private val packageTop =
    """// Generated by Mill SNAPSHOT
      |package build_.thing
      |
      |import build_.{package_ => build}
      |
      |import _root_.mill.util.TokenReaders.given
      |import _root_.mill.api.JsonFormatters.given
      |
      |
      |object package_ extends package_ {
      |
      |}
      |
      |
      |///SOURCE_CODE_START:/project/thing/package.mill
      |""".stripMargin
  private val packageOriginal =
    """package build.thing
      |
      |import mill.*
      |import mill.scalalib.*
      |
      |trait Thing extends CrossScalaModule {
      |  def foo = 2
      |}
      |
      |object `package` extends Cross[Thing]("3.3.8")
      |""".stripMargin
  private val packageUserCode =
    """//ckage build.thing
      |
      |import mill.*
      |import mill.scalalib.*
      |
      |trait Thing extends CrossScalaModule {
      |  def foo = 2
      |}
      |
      |class  package_  extends _MillRootModuleParent
      |""".stripMargin
  private val packageBottom =
    "\nabstract class _MillRootModuleParent(using _root_.sourcecode.Line, _root_.sourcecode.File) " +
      "extends _root_.mill.api.internal.SubfolderModule(_root_.build_.package_.millDiscover), " +
      "Cross[Thing](\"3.3.8\")"

  private lazy val packageRewrites = MillUserCodeRewrites.compute(
    packageOriginal,
    MillUserCodeRewrites
      .userCode(packageTop + packageUserCode + packageBottom, packageTop, packageBottom)
      .getOrElse(sys.error("no user code"))
  )

  test("user code") {
    assertEquals(
      MillUserCodeRewrites.userCode(
        packageTop + packageUserCode + packageBottom,
        packageTop,
        packageBottom
      ),
      Some(packageUserCode)
    )
    assertEquals(
      MillUserCodeRewrites.userCode(packageTop + packageUserCode, packageTop, packageBottom),
      None
    )
  }

  test("nothing to rewrite in code copied as is") {
    assert(MillUserCodeRewrites.compute(packageOriginal, packageOriginal).isEmpty)
  }

  test("unchanged original gets Mill's code") {
    assert(!packageRewrites.isEmpty)
    assertEquals(packageRewrites.applyTo(packageOriginal), packageUserCode)
  }

  test("lines added and edited elsewhere") {
    val edited = packageOriginal
      .replace("  def foo = 2\n", "  def foo = 3\n  def bar = 4\n")
      .replace("import mill.*\n", "import mill.*\nimport mill.api.*\n")
    val expected = packageUserCode
      .replace("  def foo = 2\n", "  def foo = 3\n  def bar = 4\n")
      .replace("import mill.*\n", "import mill.*\nimport mill.api.*\n")
    assertEquals(packageRewrites.applyTo(edited), expected)
  }

  test("edited object package line") {
    val edited = packageOriginal.replace(
      "object `package` extends Cross[Thing](\"3.3.8\")",
      "object `package` extends Cross[Thing](\"3.3.9\")"
    )
    // the parent can't be found as is anymore, it's left as is
    val expected = packageUserCode.replace(
      "class  package_  extends _MillRootModuleParent",
      "class  package_  extends Cross[Thing](\"3.3.9\")"
    )
    assertEquals(packageRewrites.applyTo(edited), expected)
  }

  test("edited object package line, parent unchanged") {
    val edited = packageOriginal.replace(
      "object `package` extends Cross[Thing](\"3.3.8\")",
      "object `package` extends Cross[Thing](\"3.3.8\") {\n  def a = 1\n}"
    )
    val expected = packageUserCode.replace(
      "class  package_  extends _MillRootModuleParent",
      "class  package_  extends _MillRootModuleParent {\n  def a = 1\n}"
    )
    assertEquals(packageRewrites.applyTo(edited), expected)
  }

  test("CRLF line breaks kept") {
    val original = packageOriginal.replace("\n", "\r\n")
    val rewrites =
      MillUserCodeRewrites.compute(original, packageUserCode.replace("\n", "\r\n"))
    assertEquals(rewrites.applyTo(original), packageUserCode.replace("\n", "\r\n"))
  }

  test("stripped margins left out") {
    val original =
      s"""package build
         |
         |def script = s${tq}foo
         |                |bar
         |                |$tq.stripMargin
         |
         |object `package` extends ScalaModule
         |""".stripMargin
    // Mill 1.4.0-M2 passes the user code to stripMargin
    val userCode = original.stripMargin
      .replace("package build", "//ckage build")
      .replace("object `package` extends ScalaModule", "class  package_  extends _MillRootMo")
    val rewrites = MillUserCodeRewrites.compute(original, userCode)
    assertEquals(
      rewrites.applyTo(original),
      original
        .replace("package build", "//ckage build")
        .replace("object `package` extends ScalaModule", "class  package_  extends _MillRootMo")
    )
  }

  test("rewrites not keeping lengths") {
    // like what Mill 1.1 generates
    val original =
      """object `package` extends ScalaModule {
        |  def foo = 2
        |}
        |""".stripMargin
    val userCode =
      """abstract class package_ extends _root_.mill.api.internal.SubfolderModule(_root_.build_.package_.millDiscover), ScalaModule {
        |  def foo = 2
        |}
        |""".stripMargin
    val rewrites = MillUserCodeRewrites.compute(original, userCode)
    assertEquals(rewrites.applyTo(original), userCode)
    assertEquals(
      rewrites.applyTo(original.replace("def foo = 2", "def foo = 3")),
      userCode.replace("def foo = 2", "def foo = 3")
    )
  }

  test("changes and redirects") {
    val parent  = "Cross[Thing](\"3.3.8\")"
    val applied = packageRewrites.apply(packageOriginal)
    assertEquals(
      applied.changes,
      Seq(
        MillUserCodeRewrites.Change(0, 0, "package", "//ckage"),
        MillUserCodeRewrites.Change(9, 0, "object `package` ", "class  package_  "),
        MillUserCodeRewrites.Change(9, 25, parent, "_MillRootModuleParent")
      )
    )
    // the bottom wrapper starting at line 30, column 0
    val redirects = MillUserCodeRewrites.redirects(applied.changes, packageBottom, 30, 0)
    // only the parent can be found after the user code ("package_" doesn't match "package")
    assertEquals(
      redirects,
      Seq(
        MillUserCodeRewrites.Redirect(
          9,
          25,
          parent.length,
          31,
          packageBottom.length - 1 - parent.length
        )
      )
    )
    val redirect = redirects.head
    assertEquals(redirect.toCompiler(9, 26), Some((31, redirect.compilerCol + 1)))
    assertEquals(redirect.toCompiler(9, 3), None)
    assertEquals(redirect.toUser(31, redirect.compilerCol + 6), Some((9, 31)))
    assertEquals(redirect.toUser(30, redirect.compilerCol + 6), None)
  }

  test("no redirect for edited parents") {
    val edited  = packageOriginal.replace("(\"3.3.8\")", "(\"3.3.9\")")
    val applied = packageRewrites.apply(edited)
    assertEquals(
      MillUserCodeRewrites.redirects(applied.changes, packageBottom, 30, 0),
      Nil
    )
  }

  test("tracker") {
    val dir = os.temp.dir(prefix = "plasmon-tests")
    try {
      val generated = dir / "out" / "package.mill"
      val original  = dir / "thing" / "package.mill"
      os.write(original, packageOriginal, createFolders = true)
      os.write(generated, packageTop + packageUserCode + packageBottom, createFolders = true)
      os.mtime.set(original, os.mtime(generated) - 1000L)
      val tracker = new MillUserCodeRewrites.Tracker(generated, original, packageTop, packageBottom)
      assertEquals(tracker.current().applyTo(packageOriginal), packageUserCode)

      // original saved since Mill generated its source: the former rewrites are kept
      val edited = packageOriginal.replace("  def foo = 2\n", "  def foo = 3\n")
      os.write.over(original, edited)
      os.mtime.set(original, os.mtime(generated) + 1000L)
      assertEquals(
        tracker.current().applyTo(edited),
        packageUserCode.replace("  def foo = 2\n", "  def foo = 3\n")
      )
    }
    finally os.remove.all(dir)
  }
}
